from paper_utils import Paper,fmt,interval
from figures_phase2 import main as figures

def main():
    figures();a=ROOT/'experiments/phase2/artifacts';r=read(a/'final_results.json');m=r['metrics'];lock=read(a/'evaluation_lock.json');s=m['phase2_selected'];old=m['phase1_selected'];comp=r['bootstrap']['comparisons'];audit=read(ROOT/'artifacts/audit.json');pool=lock['retrieval'];dev=read(a/'result_qwen4_fusion_d20_l2048_full.json')['metrics']['ndcg_cut_10']
    protocol=read(a/'protocol.json');baseline_dev=read(a/'result_phase1_selected_dev.json');screen_old=sum(baseline_dev['per_query'][q]['ndcg_cut_10'] for q in protocol['screen_query_ids'])/len(protocol['screen_query_ids'])
    p=Paper('Поиск русскоязычных биомедицинских текстов: смена архитектуры reranker и проверка прироста на RusBEIR')
    p.h('Abstract')
    p.p(f'Исследуется поиск на полном официальном rus-NFCorpus: 3633 документа, 324 dev и 323 test-запроса. После первоначальной композиции BM25/Qwen/BGE проведён отдельный этап сравнения архитектур: listwise Jina v3.5, более глубокий Qwen 0.6B, расширение запросов и Qwen3-Reranker-4B. Все новые решения выбирались по dev. Итоговый вариант объединяет BM25, E5-large и Qwen embedding на первом этапе, затем переоценивает top-20 с Qwen 4B в NF4. Test nDCG@10 равен {fmt(s["ndcg_cut_10"])} против опубликованного .3483 у BM25+BGE: наблюдаемый относительный прирост {100*r["relative_gain_vs_published"]:.2f}%. Против нашей предыдущей системы {fmt(old["ndcg_cut_10"])} парный 95% CI разности составляет {interval(comp["phase1_selected"]["ci95"])}. Сравнение с агрегатом статьи не является парным статистическим тестом; различия конфигурации и повторное использование исходного benchmark раскрываются.')
    p.p('Репозиторий: https://github.com/NikiBagramov/russian-biomedical-retrieval')
    p.h('1. Introduction')
    p.p('Система получает текст запроса и возвращает ранжированные идентификаторы научных документов. Основной вопрос - может ли смена готовой архитектуры и согласование первичных retrieval scores дать больший эффект, чем дальнейшее усреднение небольших rerankers. Изучаются качество первого этапа, перенос более сильного pointwise reranker и стоимость ограниченного listwise inference. Собственный вклад - воспроизводимая доменная композиция и проверка этих вариантов, без заявления новой foundation architecture.')
    p.h('2. Related Work')
    p.p('RusBEIR [1] публикует сопоставление lexical/dense/reranking на русских корпусах. На rus-NFCorpus в таблице статьи BM25 имеет .3233, mE5-large .3096, BM25+BGE .3483 nDCG@10. Расширенная работа [2], включающая FRIDA и новые корпуса, также приводит .3483 для BM25+BGE на этом dataset. Это лучший ориентир среди проверенных нами строк этих публикаций; полный мировой leaderboard нами не исчерпывается.')
    p.p('E5 [3] представляет query/document в одном пространстве. Qwen3 Embedding [4] предоставляет multilingual embeddings и pointwise yes/no rerankers разного размера. Jina v3.5 [5] использует listwise last-but-not-late взаимодействие и гибридное attention; версия 2026 служит современной альтернативой pointwise модели. ThinkQE [6] и QA-Expand [7] мотивируют расширение запроса. Наш эксперимент расширения - небольшая одношаговая двуязычная адаптация с корпусными подсказками, а не точное повторение их полных алгоритмов.')
    p.table(['Опубликованный ориентир','nDCG@10','Статус'],[['BM25 [1]','.3233','Чужой исходный запуск'],['mE5-large [1]','.3096','Чужой исходный запуск'],['BM25+BGE [1,2]','.3483','Чужой исходный запуск']],[2.5,1,2])
    p.h('3. Model Description')
    p.p('Первоначальные компоненты сохранены как baselines: BM25s Lucene k1=1.2,b=.75 на processed_title/processed_text; E5-small/large с query:/passage: и masked-mean/L2; Qwen3-Embedding-0.6B с официальным last-token pooling, L2 и biomedical query-инструкцией. Dense документы - title+newline+text, cap 512. Предыдущая итоговая версия объединяла top-100 BM25/Qwen через RRF и согласовывала BGE/Qwen 0.6B rerankers. Её код и результаты доступны в исходном commit aab0c59.')
    p.p(f'В новом первом этапе точные BM25/E5-large/Qwen embedding scores нормализуются независимо для каждого запроса по всем 3633 документам. По dev выбрана нормализация {pool["mode"]} и веса {pool["weights"]}. Для z-score вычитается среднее по документам и выполняется деление на SD с защитой 1e-12. Фиксированная сетка использовала minmax/zscore и 36 комбинаций весов; всего 36 trials на полном dev. После суммы сохраняется top-100. Никакие qrels не входят в признаки документов.')
    p.p('Qwen3-Reranker-4B читает оригинальный русский запрос и каждый top-20 документ в официальном system/user/assistant yes/no шаблоне. Prefix/suffix защищены при усечении до 2048 tokens. Score - softmax только двух yes/no logits последнего токена; это не калиброванная вероятность. Используются официальные pinned weights, NF4 double quantization и BF16 computation в bitsandbytes 0.48.2. Веса не дообучаются на benchmark. Порядок 21-100 сохраняется от первого этапа.')
    p.p('Дополнительная финальная сетка из 15 комбинаций смешивала ранги нового Qwen 4B с прежней системой и retrieval. На dev победили веса 1/0/0: добавление старого ансамбля не помогло. Итог - один более сильный reranker после новой композиции retrieval, а не ансамбль двух rerankers. Это решение не пересматривалось по test.')
    p.table(['Проверенный вариант','Сохранено','Ресурсная адаптация'],[['Jina v3.5','Released LBNL encoder/projector; official weighted query embedding fusion','Документ 512 tokens, блок<=16 docs / 4096 tokens вместо 131K полного списка'],['Qwen 0.6B deeper','Официальный yes/no template, BF16','Новый pool, top-50, cap 2048'],['Expansion','Qwen3-1.7B, greedy, без thinking','Один round: исходный query+top3unlabelled excerpts -> ru/en JSON'],['Qwen 4B selected','Официальный template/checkpoint','NF4/BF16, batch 2, top-20, cap 2048']],[1.3,2.1,2.8])
    p.h('4. Dataset')
    p.p('Источники - kaengreg/rus-nfcorpus и rus-nfcorpus-qrels на Hugging Face. Revision/SHA256 закреплены. Корпус содержит заголовки, тексты и готовые processed-поля; JSONL хранит по одному объекту в строке, qrels TSV содержит query-id/corpus-id/score. Реальные dev/test grades 1/2 сохраняются, независимо от упрощённого binary описания таблицы статьи.')
    p.table(['Split','Запросы','Qrels','Grade 2'],[[n,audit['splits'][n]['queries'],audit['splits'][n]['qrels'],audit['splits'][n]['grades'].get('2',0)] for n in ['train','dev','test']],[2,1,1.5,1])
