    p.references(['Kovalev et al. 2025. Building Russian Benchmark for Evaluation of Information Retrieval Models. https://arxiv.org/abs/2504.12879','Kovalev et al. 2025. Wikipedia-based Datasets in Russian Information Retrieval Benchmark RusBEIR. https://arxiv.org/abs/2511.05079','Wang et al. 2024. Multilingual E5 Text Embeddings: A Technical Report. https://arxiv.org/abs/2402.05672','Zhang et al. 2025. Qwen3 Embedding: Advancing Text Embedding and Reranking Through Foundation Models. https://arxiv.org/abs/2506.05176','Nasika et al. 2026. jina-reranker-v3.5: An Efficient Listwise Reranker with Hybrid Attention and Self-Distillation. https://arxiv.org/abs/2607.18152','Lei, Shen and Yates. ThinkQE: Query Expansion via an Evolving Thinking Process. EMNLP2025 Findings; revision 2026. https://arxiv.org/abs/2506.09260','QA-Expand: Multi-Question Answer Generation for Enhanced Query Expansion in Information Retrieval. 2025. https://arxiv.org/abs/2502.08557'])
    p.finish()
